from click.testing import CliRunner

base = {'keep': 'base', 'drop': None, 'replace': 'old', 'revive': None}
overrides = {'replace': None, 'revive': 'new', 'empty': '', 'added': None}
runner = CliRunner(env=base)
merged = dict(base, **overrides)
assert runner.make_env(overrides) == merged
assert runner.make_env(overrides, strip_none=False) == merged
assert runner.make_env(overrides, strip_none=True) == {'keep': 'base', 'revive': 'new', 'empty': ''}
assert runner.make_env(strip_none=True) == {'keep': 'base', 'replace': 'old'}
assert runner.make_env() == base
assert runner.make_env({}, strip_none=True) == {'keep': 'base', 'replace': 'old'}
assert CliRunner().make_env(strip_none=True) == {}
assert runner.env == base
assert overrides == {'replace': None, 'revive': 'new', 'empty': '', 'added': None}
try:
    runner.make_env(None, True)
except TypeError:
    pass
else:
    raise AssertionError('strip_none must be keyword-only')
